/* Шапка сайту */
        .header {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            height: 70px;
            background: rgba(255, 255, 255, 0.95);
            backdrop-filter: blur(10px);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 30px;
            z-index: 1000;
            box-shadow: 0 2px 20px rgba(0,0,0,0.1);
        }

        .logo {
            font-size: 28px;
            font-weight: 800;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            letter-spacing: -1px;
        }

        /* Кнопка бургер */
        .burger-btn {
            width: 50px;
            height: 50px;
            border: none;
            background: transparent;
            cursor: pointer;
            position: relative;
            z-index: 1001;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            gap: 6px;
            transition: transform 0.3s ease;
        }

        .burger-btn:hover {
            transform: scale(1.05);
        }

        .burger-line {
            width: 30px;
            height: 3px;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            border-radius: 3px;
            transition: all 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
            transform-origin: center;
        }

        /* Анімація відкритого бургера */
        .burger-btn.active .burger-line:nth-child(1) {
            transform: translateY(9px) rotate(45deg);
            width: 35px;
        }

        .burger-btn.active .burger-line:nth-child(2) {
            opacity: 0;
            transform: scaleX(0);
        }

        .burger-btn.active .burger-line:nth-child(3) {
            transform: translateY(-9px) rotate(-45deg);
            width: 35px;
        }

        /* Мобільне меню */
        .mobile-menu {
            position: fixed;
            top: 0;
            right: -100%;
            width: 100%;
            height: 100vh;
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
            z-index: 999;
            transition: right 0.5s cubic-bezier(0.77, 0, 0.175, 1);
            display: flex;
            flex-direction: column;
            padding-top: 100px;
            overflow-y: auto;
        }

        .mobile-menu.active {
            right: 0;
        }

        /* Фоновий патерн */
        .mobile-menu::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-image: 
                radial-gradient(circle at 20% 50%, rgba(120, 119, 198, 0.3) 0%, transparent 50%),
                radial-gradient(circle at 80% 80%, rgba(255, 119, 198, 0.3) 0%, transparent 50%);
            pointer-events: none;
        }

        /* Елементи меню */
        .menu-item {
            position: relative;
            padding: 20px 40px;
            color: white;
            font-size: 24px;
            font-weight: 500;
            text-decoration: none;
            display: flex;
            align-items: center;
            gap: 15px;
            transform: translateX(50px);
            opacity: 0;
            transition: all 0.3s ease;
            border-bottom: 1px solid rgba(255,255,255,0.1);
        }

        .mobile-menu.active .menu-item {
            transform: translateX(0);
            opacity: 1;
        }

        /* Затримка анімації для кожного пункту */
        .mobile-menu.active .menu-item:nth-child(1) { transition-delay: 0.1s; }
        .mobile-menu.active .menu-item:nth-child(2) { transition-delay: 0.15s; }
        .mobile-menu.active .menu-item:nth-child(3) { transition-delay: 0.2s; }
        .mobile-menu.active .menu-item:nth-child(4) { transition-delay: 0.25s; }
        .mobile-menu.active .menu-item:nth-child(5) { transition-delay: 0.3s; }
        .mobile-menu.active .menu-item:nth-child(6) { transition-delay: 0.35s; }

        .menu-item:hover {
            background: rgba(255,255,255,0.1);
            padding-left: 50px;
            color: #667eea;
        }

        .menu-icon {
            font-size: 28px;
            transition: transform 0.3s ease;
        }

        .menu-item:hover .menu-icon {
            transform: scale(1.2) rotate(10deg);
        }

        /* Підменю */
        .has-submenu {
            flex-direction: column;
            align-items: flex-start;
            cursor: pointer;
        }

        .submenu-header {
            display: flex;
            align-items: center;
            gap: 15px;
            width: 100%;
        }

        .arrow {
            margin-left: auto;
            transition: transform 0.3s ease;
            font-size: 18px;
        }

        .has-submenu.active .arrow {
            transform: rotate(180deg);
        }

        .submenu {
            max-height: 0;
            overflow: hidden;
            width: 100%;
            padding-left: 43px;
            transition: max-height 0.4s ease;
        }

        .has-submenu.active .submenu {
            max-height: 200px;
        }

        .submenu a {
            display: block;
            padding: 12px 0;
            color: rgba(255,255,255,0.7);
            font-size: 18px;
            text-decoration: none;
            transition: all 0.3s ease;
        }

        .submenu a:hover {
            color: #667eea;
            padding-left: 10px;
        }

        /* Кнопка CTA */
        .menu-cta {
            margin: 30px 40px;
            padding: 15px 30px;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            text-align: center;
            border-radius: 50px;
            font-weight: 600;
            text-decoration: none;
            transform: translateY(20px);
            opacity: 0;
            transition: all 0.3s ease;
            box-shadow: 0 10px 30px rgba(102, 126, 234, 0.4);
        }

        .mobile-menu.active .menu-cta {
            transform: translateY(0);
            opacity: 1;
            transition-delay: 0.4s;
        }

        .menu-cta:hover {
            transform: translateY(-3px);
            box-shadow: 0 15px 40px rgba(102, 126, 234, 0.6);
        }

        /* Соціальні іконки */
        .social-links {
            display: flex;
            gap: 20px;
            margin-top: auto;
            padding: 30px 40px;
            justify-content: center;
        }

        .social-links a {
            width: 45px;
            height: 45px;
            border-radius: 50%;
            background: rgba(255,255,255,0.1);
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            text-decoration: none;
            font-size: 20px;
            transition: all 0.3s ease;
            transform: translateY(20px);
            opacity: 0;
        }

        .mobile-menu.active .social-links a {
            transform: translateY(0);
            opacity: 1;
        }

        .mobile-menu.active .social-links a:nth-child(1) { transition-delay: 0.45s; }
        .mobile-menu.active .social-links a:nth-child(2) { transition-delay: 0.5s; }
        .mobile-menu.active .social-links a:nth-child(3) { transition-delay: 0.55s; }

        .social-links a:hover {
            background: #667eea;
            transform: translateY(-5px) rotate(360deg);
        }

        /* Затемнення фону */
        .overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0,0,0,0.5);
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s ease;
            z-index: 998;
            backdrop-filter: blur(3px);
        }

        .overlay.active {
            opacity: 1;
            visibility: visible;
        }

        /* Контент для демонстрації */
        .content {
            margin-top: 100px;
            padding: 40px;
            color: white;
            text-align: center;
        }

        .content h1 {
            font-size: 48px;
            margin-bottom: 20px;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
        }

        .content p {
            font-size: 20px;
            opacity: 0.9;
            max-width: 600px;
            margin: 0 auto;
            line-height: 1.6;
        }

        .demo-cards {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 30px;
            margin-top: 50px;
            max-width: 1000px;
            margin-left: auto;
            margin-right: auto;
        }

        .card {
            background: rgba(255,255,255,0.1);
            backdrop-filter: blur(10px);
            padding: 30px;
            border-radius: 20px;
            border: 1px solid rgba(255,255,255,0.2);
            transition: transform 0.3s ease;
        }

        .card:hover {
            transform: translateY(-10px);
        }

        .card-icon {
            font-size: 40px;
            margin-bottom: 15px;
        }

        .card h3 {
            font-size: 20px;
            margin-bottom: 10px;
        }

        .card p {
            font-size: 14px;
            opacity: 0.8;
        }

        /* Десктопне меню (приховане на мобільних) */
        @media (min-width: 768px) {
            .burger-btn {
                display: none;
            }

            .desktop-nav {
                display: flex;
                gap: 30px;
            }

            .desktop-nav a {
                color: #333;
                text-decoration: none;
                font-weight: 500;
                position: relative;
                padding: 5px 0;
            }

            .desktop-nav a::after {
                content: '';
                position: absolute;
                bottom: 0;
                left: 0;
                width: 0;
                height: 2px;
                background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
                transition: width 0.3s ease;
            }

            .desktop-nav a:hover::after {
                width: 100%;
            }

            .mobile-menu {
                display: none;
            }
        }

        @media (max-width: 767px) {
            .desktop-nav {
                display: none;
            }
        }

