// Отримуємо елементи
        const burgerBtn = document.getElementById('burgerBtn');
        const mobileMenu = document.getElementById('mobileMenu');
        const overlay = document.getElementById('overlay');
        const catalogItem = document.getElementById('catalogItem');
        const menuItems = document.querySelectorAll('.menu-item:not(.has-submenu)');

        // Функція відкриття/закриття меню
        function toggleMenu() {
            burgerBtn.classList.toggle('active');
            mobileMenu.classList.toggle('active');
            overlay.classList.toggle('active');
            document.body.style.overflow = mobileMenu.classList.contains('active') ? 'hidden' : '';
        }

        // Клік по бургеру
        burgerBtn.addEventListener('click', toggleMenu);

        // Клік по оверлею (закрити меню)
        overlay.addEventListener('click', toggleMenu);

        // Розкриття підменю каталогу
        catalogItem.addEventListener('click', (e) => {
            if (e.target.closest('.submenu-header')) {
                catalogItem.classList.toggle('active');
            }
        });

        // Закриття меню при кліку на пункт (крім підменю)
        menuItems.forEach(item => {
            item.addEventListener('click', () => {
                setTimeout(toggleMenu, 300); // Невелика затримка для ефекту
            });
        });

        // Закриття меню при натисканні Escape
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && mobileMenu.classList.contains('active')) {
                toggleMenu();
            }
        });

        // Запобігання прокрутці меню при відкритому підменю
        mobileMenu.addEventListener('click', (e) => {
            e.stopPropagation();
        });
